    "A condensed version of Veyn that has been crystallized. Appearance: a rough, unpolished crystal, cloudy and slightly milky rather than clear, with a faint silver-blue glow visible just beneath the surface. It looks closer to a raw mineral pulled straight from the ground than a finished gem.",
