    "Holy Flame",
    "Serapharch skill",
    "A signature skill of the Serapharch: flames made from pure holy energy that burn corruption on contact. Unlike Purgatory Flames, which simply burns until released, Holy Flame actively consumes anything tied to corrupted Veyn — demons, undead, or miasma take heavy damage from it, while anything untouched by corruption barely feels it. One of the few things capable of matching Purgatory Flames head-on; the two effectively cancel each other out if they clash directly.",
